mapper.select:
# SELECT # a.digitalId, # a.digitalname, # a.digitalimg, # a.digitalsoc, # a.release_time, # a.digitalprice, # a.digitalscreen, # a.digitalbattery, # a.digitalcamera, # b.typename, # c.brandname
SELECT a.digitalId, a.digitalname, a.digitalimg, a.digitalsoc, a.release_time, a.digitalprice, # a.digitalscreen, a.digitalbattery, # a.digitalcamera, b.typename, c.brandname FROM digital a LEFT JOIN digital_type b ON a.typeid = b.typeid LEFT JOIN digital_brand c ON a.brandid = c.brandid
AND a.digitalname LIKE CONCAT('%', #{digitalname}, '%')
AND a.typeid = b.typeid AND a.typeid = #{typeid}
AND a.brandid = c.brandid AND a.brandid = #{brandid}
AND a.release_time BETWEEN #{begin} AND #{end}
AND a.digitalbattery BETWEEN #{min} AND #{max}
